def solve(capacity, operations):
    from collections import OrderedDict
    cache, results = OrderedDict(), []
    for operation in operations:
        kind, key = operation[:2]
        if kind == 'get':
            results.append(cache.get(key))
            if key in cache: cache.move_to_end(key)
        elif capacity:
            cache[key] = operation[2]; cache.move_to_end(key)
            if len(cache) > capacity: cache.popitem(last=False)
    return results
